import {componentKinds} from './architecture-model.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/><path d="M17.5 10V6.5H14M6.5 14v3.5H10"/></svg>';
let sequence=0;
export function mountArchitecture(root,data){
  const uid='arch-'+(++sequence),controller=new AbortController(),signal=controller.signal;
  let selected='',frame=0,dialogSystem=null,restoreFocus=null;
  const byId=new Map(data.systems.map(s=>[s.id,s]));
  root.classList.add('architecture-view');
  root.innerHTML='<div class="arch-intro"><div><div class="eyebrow">06 / KIẾN TRÚC HỆ THỐNG</div><h2>'+esc(data.title)+'</h2><p>'+esc(data.description)+'</p></div><div class="arch-summary"><strong>'+data.layers.length+'<small>TẦNG</small></strong><strong>'+data.systems.length+'<small>HỆ THỐNG</small></strong><strong>'+data.connections.length+'<small>KẾT NỐI</small></strong></div></div>'+(data.isSample?'<p class="arch-sample"><span>MINH HOẠ</span> Mô hình đề xuất để xem trước, chưa phản ánh kiến trúc thực tế của BSR.</p>':'')+'<div class="arch-workspace"><div class="arch-map-panel"><div class="arch-map-toolbar"><span><i></i> BẢN ĐỒ HỆ THỐNG</span><button type="button" class="arch-reset">Bỏ chọn ↺</button></div><div class="arch-canvas"><svg class="arch-wires" aria-hidden="true"></svg><div class="arch-layers">'+(data.layers.length?data.layers.map((l,i)=>'<section class="arch-layer" style="--layer-tone:var(--arch-tone-'+i%5+')"><div class="arch-layer-heading"><span class="arch-layer-number">'+String(i+1).padStart(2,'0')+'</span><div><h3>'+esc(l.title)+'</h3><p>'+esc(l.description)+'</p></div></div><div class="arch-systems">'+(data.systems.filter(s=>s.layerId===l.id).map(s=>'<button type="button" class="arch-system" data-system="'+esc(s.id)+'" aria-pressed="false"><span class="arch-system-icon">'+icon+'</span><span><strong>'+esc(s.name)+'</strong>'+(s.status?'<small>'+esc(s.status)+'</small>':'')+'</span><span class="arch-select-arrow" aria-hidden="true">↗</span></button>').join('')||'<p class="arch-no-systems">Chưa có ứng dụng trong tầng này.</p>')+'</div></section>').join(''):'<p class="arch-empty">Kiến trúc hệ thống đang được cập nhật.</p>')+'</div></div>'+(data.security?'<div class="arch-security"><span aria-hidden="true">◇</span><div><strong>BẢO MẬT & QUẢN TRỊ XUYÊN SUỐT</strong><p>'+esc(data.security)+'</p></div></div>':'')+'<div class="arch-legend"><span><i class="arch-legend-selected"></i> Đang chọn</span><span><i class="arch-legend-related"></i> Có kết nối</span><span>→ Một chiều</span><span>↔ Hai chiều</span></div></div><aside class="arch-inspector" aria-label="Thông tin hệ thống"><div class="arch-inspector-body" aria-live="polite"></div></aside></div><dialog class="arch-dialog" aria-labelledby="'+uid+'-title"><button type="button" class="arch-dialog-close" aria-label="Đóng mô hình kiến trúc">×</button><div class="arch-detail-content"></div></dialog>';
  const canvas=root.querySelector('.arch-canvas'),wires=root.querySelector('.arch-wires'),dialog=root.querySelector('.arch-dialog'),inspector=root.querySelector('.arch-inspector-body');
  function connectionRows(connections,items,current){return connections.map(c=>{const source=items.get(c.source),target=items.get(c.target);return '<li class="arch-connection"><div><strong>'+esc(source?.name)+'</strong><span class="arch-flow-arrow" aria-label="'+(c.direction==='two-way'?'hai chiều':'một chiều')+'">'+(c.direction==='two-way'?'↔':'→')+'</span><strong>'+esc(target?.name)+'</strong></div><p>'+esc(c.label||'Kết nối')+(c.protocol?' <span class="arch-protocol">'+esc(c.protocol)+'</span>':'')+'</p>'+(current?'<button type="button" class="arch-jump" data-select="'+esc(c.source===current?c.target:c.source)+'">Chọn hệ thống liên quan ↗</button>':'')+'</li>';}).join('');}
  function select(id){
    selected=byId.has(id)?id:'';
    const system=byId.get(selected),connections=data.connections.filter(c=>c.source===selected||c.target===selected),related=new Set(connections.flatMap(c=>[c.source,c.target]));
    root.querySelector('.arch-mobile-actions')?.remove();
    root.querySelectorAll('[data-system]').forEach(button=>{const active=button.dataset.system===selected;button.setAttribute('aria-pressed',String(active));button.classList.toggle('is-related',!active&&related.has(button.dataset.system));button.classList.toggle('is-muted',!!selected&&!active&&!related.has(button.dataset.system));});
    root.querySelector('.arch-reset').disabled=!selected;
    if(!system){inspector.innerHTML='<div class="arch-inspector-empty"><span>'+icon+'</span><div class="eyebrow">KHÁM PHÁ KIẾN TRÚC</div><h3>Bắt đầu từ một ứng dụng.</h3><p>Chọn thẻ trong sơ đồ để xem các luồng kết nối và mô hình thành phần bên trong.</p><ol><li>Chọn hệ thống</li><li>Theo dõi các kết nối</li><li>Mở kiến trúc chi tiết</li></ol></div>';}else{const layer=data.layers.find(l=>l.id===system.layerId);inspector.innerHTML='<div class="arch-inspector-label">HỆ THỐNG ĐANG CHỌN</div><span class="arch-layer-tag">'+esc(layer?.title)+'</span><h3>'+esc(system.name)+'</h3><p class="arch-system-description">'+esc(system.description||'Chưa cập nhật mô tả.')+'</p><dl class="arch-meta"><div><dt>Phụ trách</dt><dd>'+esc(system.owner||'Chưa cập nhật')+'</dd></div><div><dt>Trạng thái</dt><dd>'+esc(system.status||'Chưa cập nhật')+'</dd></div></dl><button type="button" class="arch-detail-button">Xem kiến trúc chi tiết <span>↗</span></button><h4 class="arch-connection-title">'+connections.length+' kết nối trực tiếp</h4><ul class="arch-connections">'+(connectionRows(connections,byId,selected)||'<li class="arch-empty-small">Chưa thiết lập kết nối với hệ thống khác.</li>')+'</ul>';}
    if(system){const active=[...root.querySelectorAll('[data-system]')].find(b=>b.dataset.system===selected);const actions=document.createElement('div');actions.className='arch-mobile-actions';actions.innerHTML='<strong>'+esc(system.name)+'</strong><button type="button" class="arch-detail-button">Kiến trúc chi tiết ↗</button><button type="button" class="arch-view-links">'+connections.length+' kết nối ↓</button>';active.after(actions);}
    scheduleDraw();
  }
  function drawPaths(surface,svg,connections,attribute,markerId){
    const box=surface.getBoundingClientRect();if(!box.width)return;
    const nodes=new Map([...surface.querySelectorAll('['+attribute+']')].map(e=>[e.getAttribute(attribute),e.getBoundingClientRect()]));
    svg.setAttribute('viewBox','0 0 '+box.width+' '+box.height);svg.setAttribute('width',box.width);svg.setAttribute('height',box.height);
    svg.innerHTML='<defs><marker id="'+markerId+'" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto-start-reverse"><path d="M0 0 7 3.5 0 7Z" fill="#2e9150"/></marker></defs>'+connections.map((c,index)=>{const a=nodes.get(c.source),b=nodes.get(c.target);if(!a||!b)return '';let d;
      if(Math.abs(a.top-b.top)<10){const right=b.left>a.left;const x1=(right?a.right:a.left)-box.left,x2=(right?b.left:b.right)-box.left,y1=a.top+a.height/2-box.top,y2=b.top+b.height/2-box.top;const bend=Math.min(a.top,b.top)-box.top-12;d='M'+x1+' '+y1+' C'+(x1+(right?14:-14))+' '+y1+' '+x1+' '+bend+' '+((x1+x2)/2)+' '+bend+' S'+(x2+(right?-14:14))+' '+y2+' '+x2+' '+y2;
      }else{const down=b.top>a.top,sign=down?1:-1,x1=a.left+a.width/2-box.left+(index%5-2)*3,x2=b.left+b.width/2-box.left+(index%5-2)*3,y1=(down?a.bottom:a.top)-box.top,y2=(down?b.top:b.bottom)-box.top;const blocked=[...nodes].some(([id,r])=>id!==c.source&&id!==c.target&&r.bottom-box.top>Math.min(y1,y2)&&r.top-box.top<Math.max(y1,y2)&&r.right-box.left>Math.min(x1,x2)-8&&r.left-box.left<Math.max(x1,x2)+8);if(blocked){const lane=box.width-8-(index%8)*4;d='M'+x1+' '+y1+' V'+(y1+sign*8)+' H'+lane+' V'+(y2-sign*8)+' H'+x2+' V'+y2;}else{const mid=(y1+y2)/2;d='M'+x1+' '+y1+' C'+x1+' '+mid+' '+x2+' '+mid+' '+x2+' '+y2;}}
      return '<path d="'+d+'" class="arch-wire" marker-end="url(#'+markerId+')"'+(c.direction==='two-way'?' marker-start="url(#'+markerId+')"':'')+'/>';}).join('');
  }
  function scheduleDraw(){cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{drawPaths(canvas,wires,data.connections.filter(c=>c.source===selected||c.target===selected),'data-system',uid+'-arrow');if(dialog.open&&dialogSystem){const graph=dialog.querySelector('.arch-component-canvas');if(graph)drawPaths(graph,graph.querySelector('svg.arch-wires'),dialogSystem.connections,'data-component',uid+'-detail-arrow');}});}
  function showDetail(){
    const system=byId.get(selected);if(!system)return;dialogSystem=system;restoreFocus=document.activeElement;
    const items=new Map(system.components.map(c=>[c.id,c]));
    dialog.querySelector('.arch-detail-content').innerHTML='<div class="eyebrow">KIẾN TRÚC ỨNG DỤNG'+(data.isSample?' · MINH HOẠ':'')+'</div><h2 id="'+uid+'-title">'+esc(system.name)+'</h2><p class="arch-detail-description">'+esc(system.description)+'</p>'+(system.components.length?'<div class="arch-component-canvas"><svg class="arch-wires" aria-hidden="true"></svg>'+Object.entries(componentKinds).filter(([kind])=>system.components.some(c=>c.kind===kind)).map(([kind,label])=>'<section class="arch-component-tier"><h3>'+esc(label)+'</h3><div class="arch-component-grid">'+system.components.filter(c=>c.kind===kind).map(c=>'<article class="arch-component" data-component="'+esc(c.id)+'"><strong>'+esc(c.name)+'</strong><p>'+esc(c.description)+'</p></article>').join('')+'</div></section>').join('')+'</div><h3 class="arch-detail-subtitle">Luồng kết nối bên trong ứng dụng</h3><ul class="arch-connections arch-detail-connections">'+(connectionRows(system.connections,items)||'<li class="arch-empty-small">Chưa thiết lập luồng kết nối.</li>')+'</ul>':'<div class="arch-empty">Mô hình chi tiết chưa được cập nhật.</div>')+'<p class="arch-detail-note">Mũi tên biểu thị chiều kết nối. Danh sách bên dưới mô tả nội dung và giao thức của từng luồng.</p>';
    dialog.showModal();detailObserver.disconnect();const graph=dialog.querySelector('.arch-component-canvas');if(graph)detailObserver.observe(graph);scheduleDraw();
  }
  const observer=new ResizeObserver(scheduleDraw),detailObserver=new ResizeObserver(scheduleDraw);observer.observe(canvas);
  root.addEventListener('click',event=>{const system=event.target.closest('[data-system]'),jump=event.target.closest('[data-select]');if(system)select(system.dataset.system);else if(jump)select(jump.dataset.select);else if(event.target.closest('.arch-reset'))select('');else if(event.target.closest('.arch-detail-button'))showDetail();else if(event.target.closest('.arch-view-links')){inspector.scrollIntoView({behavior:'smooth',block:'start'});}else if(event.target.closest('.arch-dialog-close'))dialog.close();else if(event.target===dialog){const b=dialog.getBoundingClientRect();if(event.clientX<b.left||event.clientX>b.right||event.clientY<b.top||event.clientY>b.bottom)dialog.close();}},{signal});
  dialog.addEventListener('close',()=>{dialogSystem=null;detailObserver.disconnect();restoreFocus?.focus();},{signal});
  select('');
  return ()=>{controller.abort();observer.disconnect();detailObserver.disconnect();cancelAnimationFrame(frame);if(dialog.open)dialog.close();root.replaceChildren();};
}
